SELECT b.id, b.title, b.content, b.author_id, u.username as author_name, u.avatar_url as author_avatar, b.category, b.series_id, s.name as series_name, b.view_count, b.scheduled_at, b.status, b.created_at, b.updated_at FROM blogs b LEFT JOIN users u ON b.author_id = u.user_id LEFT JOIN series s ON b.series_id = s.id
b.status = 1
AND b.title LIKE concat('%', #{keyword}, '%')
AND b.series_id = #{seriesId}
AND b.category = #{category}
ORDER BY b.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM blogs b

    b.status = 1

        AND b.title LIKE concat('%', #{keyword}, '%')


        AND b.series_id = #{seriesId}


        AND b.category = #{category}

SELECT b.id, b.title, b.content, b.author_id, u.username as author_name, u.avatar_url as author_avatar, b.category, b.series_id, s.name as series_name, b.view_count, b.scheduled_at, b.status, b.created_at, b.updated_at FROM blogs b LEFT JOIN users u ON b.author_id = u.user_id LEFT JOIN series s ON b.series_id = s.id WHERE b.author_id = #{authorId}
AND b.status = #{status}
ORDER BY b.created_at DESC LIMIT #{limit} OFFSET #{offset}

